-- ShopGuard Initial Migration
-- Run with: psql $DATABASE_URL < migrations/0001_initial.sql

-- Enums
CREATE TYPE role AS ENUM ('OWNER','ADMIN','MANAGER','INVESTIGATOR','VIEWER');
CREATE TYPE severity AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL');
CREATE TYPE risk_level AS ENUM ('LOW','MEDIUM','HIGH');
CREATE TYPE incident_status AS ENUM ('OPEN','UNDER_REVIEW','RESOLVED','DISMISSED');
CREATE TYPE review_label AS ENUM ('VALID_INCIDENT','FALSE_POSITIVE','NEEDS_INVESTIGATION','NOT_ENOUGH_EVIDENCE');
CREATE TYPE tx_status AS ENUM ('COMPLETED','VOIDED','REFUNDED','PARTIAL_REFUND','PENDING','CANCELLED');
CREATE TYPE import_status AS ENUM ('PENDING','PROCESSING','COMPLETED','FAILED','CANCELLED');
CREATE TYPE notif_channel AS ENUM ('EMAIL','WHATSAPP','SMS','IN_APP');
CREATE TYPE notif_type AS ENUM ('INCIDENT_CREATED','INCIDENT_FOLLOWUP','INCIDENT_ESCALATION','DAILY_REPORT','SYSTEM_ALERT');
CREATE TYPE notif_status AS ENUM ('PENDING','SENT','DELIVERED','FAILED','SKIPPED');
CREATE TYPE model_status AS ENUM ('CANDIDATE','PRODUCTION','RETIRED','FAILED');
CREATE TYPE baseline_conf AS ENUM ('LOW','MEDIUM','HIGH');
CREATE TYPE subscription_plan AS ENUM ('TRIAL','STARTER','GROWTH','MULTI_LOCATION','ENTERPRISE');
CREATE TYPE subscription_status AS ENUM ('ACTIVE','TRIALING','PAST_DUE','CANCELLED','EXPIRED');

-- Core tables
CREATE TABLE organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug VARCHAR(100) NOT NULL UNIQUE, timezone VARCHAR(50) NOT NULL DEFAULT 'Asia/Karachi', currency VARCHAR(10) NOT NULL DEFAULT 'PKR', locale VARCHAR(10) NOT NULL DEFAULT 'en', business_type TEXT, is_demo BOOLEAN NOT NULL DEFAULT FALSE, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE org_settings (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL UNIQUE REFERENCES organizations(id) ON DELETE CASCADE, risk_threshold_high NUMERIC(4,2) NOT NULL DEFAULT '0.70', risk_threshold_medium NUMERIC(4,2) NOT NULL DEFAULT '0.40', min_sample_size_employee INT NOT NULL DEFAULT 20, min_sample_size_store INT NOT NULL DEFAULT 100, follow_up_high_hours INT NOT NULL DEFAULT 4, follow_up_medium_hours INT NOT NULL DEFAULT 24, follow_up_low_hours INT NOT NULL DEFAULT 72, max_follow_ups INT NOT NULL DEFAULT 3, data_retention_days INT NOT NULL DEFAULT 730, enable_rules BOOLEAN NOT NULL DEFAULT TRUE, enable_ml BOOLEAN NOT NULL DEFAULT TRUE, enable_notifications BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE users (id TEXT PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash TEXT NOT NULL, name TEXT NOT NULL, phone TEXT, email_verified BOOLEAN NOT NULL DEFAULT FALSE, verify_token TEXT, reset_token TEXT, reset_token_expiry TIMESTAMPTZ, last_login_at TIMESTAMPTZ, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token TEXT NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE memberships (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role role NOT NULL DEFAULT 'VIEWER', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(organization_id, user_id));
CREATE TABLE invitations (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, email VARCHAR(255) NOT NULL, role role NOT NULL DEFAULT 'VIEWER', token TEXT NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, accepted_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE stores (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, code TEXT, address TEXT, timezone TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, opening_hour INT NOT NULL DEFAULT 8, closing_hour INT NOT NULL DEFAULT 22, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE registers (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, store_id TEXT NOT NULL REFERENCES stores(id) ON DELETE CASCADE, name TEXT NOT NULL, code TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE employees (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, external_id TEXT, name TEXT NOT NULL, code TEXT, email TEXT, phone TEXT, role TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, hired_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE transactions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, store_id TEXT NOT NULL REFERENCES stores(id), register_id TEXT REFERENCES registers(id), employee_id TEXT REFERENCES employees(id), external_transaction_id TEXT, timestamp TIMESTAMPTZ NOT NULL, currency VARCHAR(10) NOT NULL DEFAULT 'PKR', gross_amount NUMERIC(18,2) NOT NULL, discount_amount NUMERIC(18,2) NOT NULL DEFAULT '0', refund_amount NUMERIC(18,2) NOT NULL DEFAULT '0', net_amount NUMERIC(18,2) NOT NULL, payment_method TEXT, transaction_status tx_status NOT NULL DEFAULT 'COMPLETED', item_count INT, duration_seconds INT, is_void BOOLEAN NOT NULL DEFAULT FALSE, is_refund BOOLEAN NOT NULL DEFAULT FALSE, is_no_sale BOOLEAN NOT NULL DEFAULT FALSE, has_price_override BOOLEAN NOT NULL DEFAULT FALSE, discount_percent NUMERIC(5,2), notes TEXT, metadata JSONB, source TEXT NOT NULL DEFAULT 'csv', source_record_id TEXT, import_job_id TEXT, is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(organization_id, external_transaction_id, source));
CREATE TABLE cash_sessions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), store_id TEXT NOT NULL REFERENCES stores(id), register_id TEXT REFERENCES registers(id), employee_id TEXT REFERENCES employees(id), date DATE NOT NULL, shift_type TEXT, opening_cash NUMERIC(18,2) NOT NULL, cash_sales NUMERIC(18,2) NOT NULL DEFAULT '0', cash_refunds NUMERIC(18,2) NOT NULL DEFAULT '0', cash_adjustments NUMERIC(18,2) NOT NULL DEFAULT '0', expected_cash NUMERIC(18,2) NOT NULL, counted_cash NUMERIC(18,2), variance NUMERIC(18,2), is_reconciled BOOLEAN NOT NULL DEFAULT FALSE, notes TEXT, is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE incidents (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), store_id TEXT REFERENCES stores(id), register_id TEXT REFERENCES registers(id), employee_id TEXT REFERENCES employees(id), severity severity NOT NULL, risk_level risk_level NOT NULL, status incident_status NOT NULL DEFAULT 'OPEN', type TEXT NOT NULL, title TEXT NOT NULL, summary TEXT NOT NULL, why_flagged JSONB NOT NULL DEFAULT '[]', rule_ids JSONB NOT NULL DEFAULT '[]', model_version TEXT, feature_version TEXT, ml_score NUMERIC(5,4), next_follow_up_at TIMESTAMPTZ, follow_up_count INT NOT NULL DEFAULT 0, escalation_level INT NOT NULL DEFAULT 0, is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE incident_evidence (id TEXT PRIMARY KEY, incident_id TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, rule_id TEXT, type TEXT NOT NULL, description TEXT NOT NULL, severity severity NOT NULL, score NUMERIC(5,4) NOT NULL DEFAULT '0', metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE incident_transactions (incident_id TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, transaction_id TEXT NOT NULL REFERENCES transactions(id), PRIMARY KEY(incident_id, transaction_id));
CREATE TABLE incident_reviews (id TEXT PRIMARY KEY, incident_id TEXT NOT NULL REFERENCES incidents(id), user_id TEXT NOT NULL REFERENCES users(id), label review_label NOT NULL, notes TEXT, model_version TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE incident_relations (primary_incident_id TEXT NOT NULL REFERENCES incidents(id), related_incident_id TEXT NOT NULL REFERENCES incidents(id), relation_type TEXT NOT NULL, PRIMARY KEY(primary_incident_id, related_incident_id));
CREATE TABLE employee_baselines (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, employee_id TEXT NOT NULL REFERENCES employees(id), period TEXT NOT NULL, confidence baseline_conf NOT NULL, tx_count INT NOT NULL DEFAULT 0, avg_amount NUMERIC(18,2), median_amount NUMERIC(18,2), std_amount NUMERIC(18,2), tx_per_hour NUMERIC(8,4), void_rate NUMERIC(6,5), refund_rate NUMERIC(6,5), discount_rate NUMERIC(6,5), price_override_rate NUMERIC(6,5), avg_discount_pct NUMERIC(6,3), computed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(employee_id, period));
CREATE TABLE store_baselines (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, store_id TEXT NOT NULL REFERENCES stores(id), period TEXT NOT NULL, confidence baseline_conf NOT NULL, tx_count INT NOT NULL DEFAULT 0, avg_amount NUMERIC(18,2), median_amount NUMERIC(18,2), std_amount NUMERIC(18,2), void_rate NUMERIC(6,5), refund_rate NUMERIC(6,5), discount_rate NUMERIC(6,5), hourly_volume JSONB, dow_volume JSONB, computed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(store_id, period));
CREATE TABLE register_baselines (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, register_id TEXT NOT NULL REFERENCES registers(id), period TEXT NOT NULL, confidence baseline_conf NOT NULL, tx_count INT NOT NULL DEFAULT 0, no_sale_rate NUMERIC(6,5), void_rate NUMERIC(6,5), refund_rate NUMERIC(6,5), cash_variance_avg NUMERIC(18,2), computed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(register_id, period));
CREATE TABLE time_baselines (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, store_id TEXT NOT NULL REFERENCES stores(id), hour INT, day_of_week INT, avg_volume NUMERIC(8,2), avg_amount NUMERIC(18,2), avg_void_rate NUMERIC(6,5), sample_weeks INT NOT NULL DEFAULT 0, computed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(store_id, hour, day_of_week));
CREATE TABLE feature_snapshots (id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL UNIQUE REFERENCES transactions(id), organization_id TEXT NOT NULL, features JSONB NOT NULL, feature_version TEXT NOT NULL DEFAULT '1.0.0', ml_score NUMERIC(6,5), ml_model TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE model_versions (id TEXT PRIMARY KEY, organization_id TEXT, name TEXT NOT NULL, model_type TEXT NOT NULL, version TEXT NOT NULL, feature_version TEXT NOT NULL DEFAULT '1.0.0', status model_status NOT NULL DEFAULT 'CANDIDATE', is_production BOOLEAN NOT NULL DEFAULT FALSE, training_sample_count INT, training_dataset_id TEXT, metrics JSONB, hyperparameters JSONB, artifact_path TEXT, acceptance_criteria JSONB, deployed_at TIMESTAMPTZ, retired_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE training_datasets (id TEXT PRIMARY KEY, organization_id TEXT, name TEXT NOT NULL, feature_version TEXT NOT NULL, sample_count INT NOT NULL DEFAULT 0, positive_label_count INT NOT NULL DEFAULT 0, negative_label_count INT NOT NULL DEFAULT 0, unlabeled_count INT NOT NULL DEFAULT 0, is_demo BOOLEAN NOT NULL DEFAULT FALSE, from_date TIMESTAMPTZ, to_date TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE training_runs (id TEXT PRIMARY KEY, organization_id TEXT, dataset_id TEXT REFERENCES training_datasets(id), model_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', triggered_by TEXT NOT NULL, started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, duration_seconds INT, candidate_model_id TEXT, production_model_id TEXT, deployed BOOLEAN NOT NULL DEFAULT FALSE, deployment_reason TEXT, rejection_reason TEXT, metrics JSONB, error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE import_jobs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), store_id TEXT REFERENCES stores(id), filename TEXT NOT NULL, original_name TEXT NOT NULL, file_size INT NOT NULL, status import_status NOT NULL DEFAULT 'PENDING', mapping_id TEXT, row_count INT, imported_count INT NOT NULL DEFAULT 0, skipped_count INT NOT NULL DEFAULT 0, error_count INT NOT NULL DEFAULT 0, quality_report JSONB, error TEXT, started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE import_mappings (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, pos_type TEXT, column_mappings JSONB NOT NULL, transformations JSONB, is_default BOOLEAN NOT NULL DEFAULT FALSE, use_count INT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE data_quality_issues (id TEXT PRIMARY KEY, import_job_id TEXT NOT NULL REFERENCES import_jobs(id), row_number INT, field TEXT, issue_type TEXT NOT NULL, description TEXT NOT NULL, raw_value TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE notification_preferences (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), channel notif_channel NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, high_priority BOOLEAN NOT NULL DEFAULT TRUE, medium_priority BOOLEAN NOT NULL DEFAULT TRUE, low_priority BOOLEAN NOT NULL DEFAULT FALSE, email TEXT, phone TEXT, batch_delay_minutes INT NOT NULL DEFAULT 60, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE notification_attempts (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), incident_id TEXT REFERENCES incidents(id), channel notif_channel NOT NULL, type notif_type NOT NULL, recipient TEXT NOT NULL, status notif_status NOT NULL DEFAULT 'PENDING', provider_message_id TEXT, failure_reason TEXT, retry_count INT NOT NULL DEFAULT 0, sent_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE reports (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), store_id TEXT REFERENCES stores(id), type TEXT NOT NULL, title TEXT NOT NULL, date DATE NOT NULL, summary JSONB NOT NULL, is_generated BOOLEAN NOT NULL DEFAULT FALSE, is_demo BOOLEAN NOT NULL DEFAULT FALSE, generated_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE audit_logs (id TEXT PRIMARY KEY, organization_id TEXT REFERENCES organizations(id), user_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity TEXT, entity_id TEXT, metadata JSONB, ip_address TEXT, user_agent TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE rule_configs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), rule_id TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, severity severity NOT NULL DEFAULT 'MEDIUM', thresholds JSONB, min_sample_size INT NOT NULL DEFAULT 10, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(organization_id, rule_id));
CREATE TABLE subscriptions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL UNIQUE REFERENCES organizations(id), plan subscription_plan NOT NULL DEFAULT 'TRIAL', status subscription_status NOT NULL DEFAULT 'ACTIVE', trial_ends_at TIMESTAMPTZ, current_period_start TIMESTAMPTZ, current_period_end TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE analysis_jobs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, import_job_id TEXT, status TEXT NOT NULL DEFAULT 'PENDING', transaction_count INT NOT NULL DEFAULT 0, processed_count INT NOT NULL DEFAULT 0, incidents_created INT NOT NULL DEFAULT 0, baseline_updated BOOLEAN NOT NULL DEFAULT FALSE, error TEXT, started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE job_logs (id TEXT PRIMARY KEY, organization_id TEXT, job_type TEXT NOT NULL, job_id TEXT NOT NULL, status TEXT NOT NULL, attempt INT NOT NULL DEFAULT 1, payload JSONB, result JSONB, error TEXT, duration_ms INT, started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), completed_at TIMESTAMPTZ);

-- Indexes
CREATE INDEX idx_transactions_org_timestamp ON transactions(organization_id, timestamp);
CREATE INDEX idx_transactions_org_employee ON transactions(organization_id, employee_id);
CREATE INDEX idx_transactions_org_store ON transactions(organization_id, store_id);
CREATE INDEX idx_transactions_is_void ON transactions(is_void) WHERE is_void = TRUE;
CREATE INDEX idx_transactions_import_job ON transactions(import_job_id);
CREATE INDEX idx_incidents_org_status ON incidents(organization_id, status);
CREATE INDEX idx_incidents_org_severity ON incidents(organization_id, severity);
CREATE INDEX idx_incidents_next_followup ON incidents(next_follow_up_at) WHERE status = 'OPEN';
CREATE INDEX idx_sessions_token ON sessions(token);
CREATE INDEX idx_audit_logs_org ON audit_logs(organization_id, created_at);

-- Additional indexes for common query patterns (added in v3 hardening)
CREATE INDEX idx_employees_org_active ON employees(organization_id, is_active);
CREATE INDEX idx_stores_org_active ON stores(organization_id, is_active);
CREATE INDEX idx_registers_org ON registers(organization_id);
CREATE INDEX idx_import_jobs_org_status ON import_jobs(organization_id, status);
CREATE INDEX idx_notification_attempts_incident ON notification_attempts(incident_id);
CREATE INDEX idx_notification_attempts_org_status ON notification_attempts(organization_id, status);
CREATE INDEX idx_feature_snapshots_org ON feature_snapshots(organization_id);
CREATE INDEX idx_analysis_jobs_org_import ON analysis_jobs(organization_id, import_job_id);
CREATE INDEX idx_incidents_org_employee ON incidents(organization_id, employee_id);
CREATE INDEX idx_incidents_org_created ON incidents(organization_id, created_at DESC);
CREATE INDEX idx_employee_baselines_org ON employee_baselines(organization_id);
CREATE INDEX idx_store_baselines_org ON store_baselines(organization_id);
CREATE INDEX idx_reports_org_date ON reports(organization_id, type, date DESC);
CREATE INDEX idx_cash_sessions_org_date ON cash_sessions(organization_id, date DESC);
CREATE INDEX idx_transactions_org_register ON transactions(organization_id, register_id);
CREATE INDEX idx_job_logs_org_type ON job_logs(organization_id, job_type, started_at DESC);
